import{_ as i,a0 as l,w as s,s as p,I as n,x as e,a1 as t,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何配置一个 Docker Swarm 原生集群 | LCTT x X-CMD","titleTemplate":false,"description":"如何配置一个 Docker Swarm 原生集群 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何配置一个 Docker Swarm 原生集群 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何配置一个 Docker Swarm 原生集群 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150612 How to Configure Swarm Native Clustering for Docker","title":"如何配置一个 Docker Swarm 原生集群","tag":"201507","desc":""},"relativePath":"201507/20150612 How to Configure Swarm Native Clustering for Docker.md","filePath":"[post].md"}'),m={name:"201507/20150612 How to Configure Swarm Native Clustering for Docker.md"};function c(w,r,g,k,u,h){const a=l("Link");return s(),p("div",null,[r[16]||(r[16]=n("h1",{id:"如何配置一个-docker-swarm-原生集群",tabindex:"-1"},[e("如何配置一个 Docker Swarm 原生集群 "),n("a",{class:"header-anchor",href:"#如何配置一个-docker-swarm-原生集群","aria-label":"Permalink to “如何配置一个 Docker Swarm 原生集群”"},"​")],-1)),n("p",null,[r[1]||(r[1]=e("嗨，大家好。今天我们来学一学Swarm相关的内容吧，我们将学习通过Swarm来创建Docker原生集群。",-1)),t(a,{href:"https://docs.docker.com/swarm/"},{default:o(()=>[...r[0]||(r[0]=[e("Docker Swarm",-1)])]),_:1}),r[2]||(r[2]=e("是用于Docker的原生集群项目，它可以将一个Docker主机池转换成单个的虚拟主机。Swarm工作于标准的Docker API，所以任何可以和Docker守护进程通信的工具都可以使用Swarm来透明地伸缩到多个主机上。就像其它Docker项目一样，Swarm遵循“内置电池，并可拆卸”的原则（LCTT 译注：batteries included，内置电池原来是 Python 圈里面对 Python 的一种赞誉，指自给自足，无需外求的丰富环境；but removable，并可拆卸应该指的是非强制耦合）。它附带有一个开箱即用的简单的后端调度程序，而且作为初始开发套件，也为其开发了一个可插拔不同后端的API。其目标在于为一些简单的使用情况提供一个平滑的、开箱即用的体验，并且它允许切换为更强大的后端，如Mesos，以用于大规模生产环境部署。Swarm配置和使用极其简单。",-1))]),r[17]||(r[17]=d(`<p>这里给大家提供Swarm 0.2开箱的即用一些特性。</p><ol><li>Swarm 0.2.0大约85%与Docker引擎兼容。</li><li>它支持资源管理。</li><li>它具有一些带有限制和类同功能的高级调度特性。</li><li>它支持多个发现后端（hubs，consul，etcd，zookeeper）</li><li>它使用TLS加密方法进行安全通信和验证。</li></ol><p>那么，我们来看一看Swarm的一些相当简单而简用的使用步骤吧。</p><h3 id="_1-运行swarm的先决条件" tabindex="-1">1. 运行Swarm的先决条件 <a class="header-anchor" href="#_1-运行swarm的先决条件" aria-label="Permalink to “1. 运行Swarm的先决条件”">​</a></h3><p>我们必须在所有节点安装Docker 1.4.0或更高版本。虽然各个节点的IP地址不需要要公共地址，但是Swarm管理器必须可以通过网络访问各个节点。</p><p><strong>注意</strong>：Swarm当前还处于beta版本，因此功能特性等还有可能发生改变，我们不推荐你在生产环境中使用。</p><h3 id="_2-创建swarm集群" tabindex="-1">2. 创建Swarm集群 <a class="header-anchor" href="#_2-创建swarm集群" aria-label="Permalink to “2. 创建Swarm集群”">​</a></h3><p>现在，我们将通过运行下面的命令来创建Swarm集群。各个节点都将运行一个swarm节点代理，该代理会注册、监控相关的Docker守护进程，并更新发现后端获取的节点状态。下面的命令会返回一个唯一的集群ID标记，在启动节点上的Swarm代理时会用到它。</p><p>在集群管理器中：</p><pre><code># docker run swarm create
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/creating-swarm-cluster.png" alt="Creating Swarm Cluster"></p><h3 id="_3-启动各个节点上的docker守护进程" tabindex="-1">3. 启动各个节点上的Docker守护进程 <a class="header-anchor" href="#_3-启动各个节点上的docker守护进程" aria-label="Permalink to “3. 启动各个节点上的Docker守护进程”">​</a></h3><p>我们需要登录进我们将用来创建集群的每个节点，并在其上使用-H标记启动Docker守护进程。它会保证Swarm管理器能够通过TCP访问到各个节点上的Docker远程API。要启动Docker守护进程，我们需要在各个节点内部运行以下命令。</p><pre><code># docker -H tcp://0.0.0.0:2375 -d
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/starting-docker-daemon.png" alt="Starting Docker Daemon"></p><h3 id="_4-添加节点" tabindex="-1">4. 添加节点 <a class="header-anchor" href="#_4-添加节点" aria-label="Permalink to “4. 添加节点”">​</a></h3><p>在启用Docker守护进程后，我们需要添加Swarm节点到发现服务，我们必须确保节点IP可从Swarm管理器访问到。要完成该操作，我们需要运行以下命令。</p><pre><code># docker run -d swarm join --addr=&lt;node_ip&gt;:2375 token://&lt;cluster_id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/adding-nodes-to-cluster.png" alt="Adding Nodes to Cluster"></p><p><strong>注意</strong>：我们需要用步骤2中获取到的节点IP地址和集群ID替换这里的&lt;node_ip&gt;和&lt;cluster_id&gt;。</p><h3 id="_5-开启swarm管理器" tabindex="-1">5. 开启Swarm管理器 <a class="header-anchor" href="#_5-开启swarm管理器" aria-label="Permalink to “5. 开启Swarm管理器”">​</a></h3><p>现在，由于我们已经获得了连接到集群的节点，我们将启动swarm管理器。我们需要在节点中运行以下命令。</p><pre><code># docker run -d -p &lt;swarm_port&gt;:2375 swarm manage token://&lt;cluster_id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/starting-swarm-manager.png" alt="Starting Swarm Manager"></p><h3 id="_6-检查配置" tabindex="-1">6. 检查配置 <a class="header-anchor" href="#_6-检查配置" aria-label="Permalink to “6. 检查配置”">​</a></h3><p>一旦管理运行起来后，我们可以通过运行以下命令来检查配置。</p><pre><code># docker -H tcp://&lt;manager_ip:manager_port&gt; info
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/accessing-swarm-cluster.png" alt="Accessing Swarm Clusters"></p><p><strong>注意</strong>：我们需要替换&lt;manager_ip:manager_port&gt;为运行swarm管理器的主机的IP地址和端口。</p><h3 id="_7-使用docker-cli来访问节点" tabindex="-1">7. 使用docker CLI来访问节点 <a class="header-anchor" href="#_7-使用docker-cli来访问节点" aria-label="Permalink to “7. 使用docker CLI来访问节点”">​</a></h3><p>在一切都像上面说得那样完美地完成后，这一部分是Docker Swarm最为重要的部分。我们可以使用Docker CLI来访问节点，并在节点上运行容器。</p><pre><code># docker -H tcp://&lt;manager_ip:manager_port&gt; info
# docker -H tcp://&lt;manager_ip:manager_port&gt; run ...
</code></pre><h3 id="_8-监听集群中的节点" tabindex="-1">8. 监听集群中的节点 <a class="header-anchor" href="#_8-监听集群中的节点" aria-label="Permalink to “8. 监听集群中的节点”">​</a></h3><p>我们可以使用swarm list命令来获取所有运行中节点的列表。</p><pre><code># docker run --rm swarm list token://&lt;cluster_id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/listing-swarm-nodes.png" alt="Listing Swarm Nodes"></p><h3 id="尾声" tabindex="-1">尾声 <a class="header-anchor" href="#尾声" aria-label="Permalink to “尾声”">​</a></h3><p>Swarm真的是一个有着相当不错的功能的docker，它可以用于创建和管理集群。它相当易于配置和使用，当我们在它上面使用限制器和类同器时它更为出色。高级调度程序是一个相当不错的特性，它可以应用过滤器来通过端口、标签、健康状况来排除节点，并且它使用策略来挑选最佳节点。那么，如果你有任何问题、评论、反馈，请在下面的评论框中写出来吧，好让我们知道哪些材料需要补充或改进。谢谢大家了！尽情享受吧 😃</p><hr>`,39)),n("p",null,[r[4]||(r[4]=e("via: ",-1)),t(a,{href:"http://linoxide.com/linux-how-to/configure-swarm-clustering-docker/"},{default:o(()=>[...r[3]||(r[3]=[e("http://linoxide.com/linux-how-to/configure-swarm-clustering-docker/",-1)])]),_:1})]),n("p",null,[r[8]||(r[8]=e("作者：",-1)),t(a,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...r[5]||(r[5]=[e("Arun Pyasi",-1)])]),_:1}),r[9]||(r[9]=e(" 译者：",-1)),t(a,{href:"https://github.com/GOLinux"},{default:o(()=>[...r[6]||(r[6]=[e("GOLinux",-1)])]),_:1}),r[10]||(r[10]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...r[7]||(r[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[r[13]||(r[13]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...r[11]||(r[11]=[e("LCTT",-1)])]),_:1}),r[14]||(r[14]=e(" 原创翻译，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...r[12]||(r[12]=[e("Linux中国",-1)])]),_:1}),r[15]||(r[15]=e(" 荣誉推出",-1))])])}const x=i(m,[["render",c]]);export{D as __pageData,x as default};
